window.YV_TEXT=Object.assign(window.YV_TEXT||{},{"自定义噪音模型的后验抽样与诊断":{"en":"Posterior sampling and diagnostics for custom noise models","fr":"Échantillonnage postérieur et diagnostics des modèles de bruit","es":"Muestreo posterior y diagnóstico de modelos de ruido","eu":"Zarata-ereduen laginketa posteriorra eta diagnostikoa"},"配套模型、比对或模拟脚本须另行准备；此处保存规划配方。":{"en":"Prepare the matching model, alignment or simulation script; this record stores a planning recipe.","fr":"Préparez le modèle, l’alignement ou le script adapté ; cette fiche conserve la recette de planification.","es":"Prepare el modelo, alineamiento o script correspondiente; esta ficha guarda la receta de planificación.","eu":"Prestatu dagokion eredu, lerrokatze edo simulazio-scripta; erregistro honek plangintzako errezeta gordetzen du."},"模型结果、区间与可复核的诊断":{"en":"Model results, intervals and reproducible diagnostics","fr":"Résultats, intervalles et diagnostics reproductibles","es":"Resultados, intervalos y diagnósticos reproducibles","eu":"Eredu-emaitzak, tarteak eta diagnostiko erreproduzigarriak"},"模型文件与运行环境":{"en":"Model files and runtime","fr":"Fichiers du modèle et environnement","es":"Archivos del modelo y entorno","eu":"Eredu-fitxategiak eta exekuzio-ingurunea"},"按研究问题选择模型、参数与种子；保存软件版本和完整调用。":{"en":"Choose the model, parameters and seed for the question; retain software versions and the complete call.","fr":"Choisissez modèle, paramètres et graine selon la question ; conservez versions et appel complet.","es":"Elija modelo, parámetros y semilla según la pregunta; guarde versiones y llamada completa.","eu":"Aukeratu eredua, parametroak eta hazia galderaren arabera; gorde bertsioak eta dei osoa."},"检查性状尺度、菌株顺序、重复结构与估计误差；用匹配设计的模拟检查校准。":{"en":"Check trait scale, strain order, replication and estimation error; assess calibration with design-matched simulations.","fr":"Vérifiez l’échelle, l’ordre des souches, les réplicats et l’erreur d’estimation ; calibrez par simulation adaptée.","es":"Revise escala, orden de cepas, réplicas y error de estimación; calibre con simulaciones del diseño.","eu":"Egiaztatu eskala, anduien ordena, erreplikazioa eta estimazio-errorea; kalibratu diseinuari egokitutako simulazioekin."},"官方方法文档":{"en":"Official method documentation","fr":"Documentation officielle","es":"Documentación oficial","eu":"Metodoaren dokumentazio ofiziala"},"方法论文":{"en":"Method paper","fr":"Publication méthodologique","es":"Artículo metodológico","eu":"Metodo-artikulua"},"贝叶斯计算的模拟校准":{"en":"Simulation calibration of Bayesian computation","fr":"Calibration simulée du calcul bayésien","es":"Calibración simulada del cálculo bayesiano","eu":"Kalkulu bayestarraren simulazio-kalibrazioa"},"含亲缘与测量方差的贝叶斯混合模型":{"en":"Bayesian mixed models with relatedness and measurement variance","fr":"Modèles mixtes bayésiens avec parenté et variance de mesure","es":"Modelos mixtos bayesianos con parentesco y varianza de medida","eu":"Ahaidetasun eta neurketa-bariantza dituzten eredu misto bayestarrak"},"ginverse 使用亲缘协方差的逆；mev 使用同尺度抽样方差。后验 SD 需另行校准。":{"en":"ginverse takes inverse relationship covariance; mev takes sampling variance on the response scale. Posterior SD requires separate calibration.","fr":"ginverse reçoit l’inverse de la covariance ; mev la variance d’échantillonnage sur l’échelle de réponse. Calibrez séparément l’écart-type postérieur.","es":"ginverse recibe la covarianza inversa; mev la varianza de muestreo en la escala de respuesta. Calibre aparte la DE posterior.","eu":"ginverse-k ahaidetasun-kobariantzaren alderantzizkoa hartzen du; mev-k erantzun-eskalako laginketa-bariantza. Kalibratu desbideratze posteriorra bereiz."},"连续噪音性状的多变量演变模型":{"en":"Multivariate evolution of continuous noise traits","fr":"Évolution multivariée des caractères de bruit","es":"Evolución multivariada de rasgos de ruido","eu":"Zarata-ezaugarri jarraituen eboluzio aldagai anitzekoa"},"核对根、末端匹配、分支单位及重组／杂交敏感性；细胞状态轨迹单独分析。":{"en":"Check rooting, tip matching, branch units and recombination/hybridization sensitivity; analyse cell-state trajectories separately.","fr":"Vérifiez racine, correspondances, unités et sensibilité à la recombinaison/hybridation ; analysez séparément les trajectoires cellulaires.","es":"Revise raíz, correspondencias, unidades y sensibilidad a recombinación/hibridación; analice aparte trayectorias celulares.","eu":"Egiaztatu erroa, muturren parekatzea, unitateak eta birkonbinazio/hibridazioarekiko sentikortasuna; aztertu zelula-ibilbideak bereiz."},"error 输入抽样方差，按树末端与性状列对齐；OU 拟合本身不确定历史选择。":{"en":"error takes sampling variances aligned to tips and traits; an OU fit alone does not establish historical selection.","fr":"error reçoit des variances alignées aux feuilles et caractères ; OU seul ne démontre pas une sélection historique.","es":"error recibe varianzas alineadas con puntas y rasgos; ajustar OU no demuestra selección histórica.","eu":"error-ek mutur eta ezaugarriekin lerrokatutako laginketa-bariantzak hartzen ditu; OU doikuntzak ez du hautespen historikoa frogatzen."},"基因组序列的最大似然菌株树":{"en":"Maximum-likelihood strain trees from genomic sequences","fr":"Arbres de souches par maximum de vraisemblance","es":"Árboles de cepas por máxima verosimilitud","eu":"Andui-zuhaitzak egiantzekotasun handienaz"},"菌株树的替代最大似然实现":{"en":"Alternative maximum-likelihood strain-tree inference","fr":"Inférence alternative des arbres par maximum de vraisemblance","es":"Inferencia alternativa de árboles por máxima verosimilitud","eu":"Andui-zuhaitzen egiantzekotasun bidezko ordezko inferentzia"},"有明确校准的贝叶斯菌株历史模型":{"en":"Calibrated Bayesian strain-history models","fr":"Modèles bayésiens calibrés de l’histoire des souches","es":"Modelos bayesianos calibrados de historia de cepas","eu":"Anduien historiaren eredu bayestar kalibratuak"},"贝叶斯树与连续性状演变模型":{"en":"Bayesian trees and continuous-trait evolution","fr":"Arbres bayésiens et évolution des caractères continus","es":"Árboles bayesianos y evolución de rasgos continuos","eu":"Zuhaitz bayestarrak eta ezaugarri jarraituen eboluzioa"},"菌株树与噪音注释的联合展示":{"en":"Joint display of strain trees and noise annotations","fr":"Affichage conjoint des arbres et annotations de bruit","es":"Visualización conjunta de árboles y anotaciones de ruido","eu":"Andui-zuhaitzen eta zarata-oharren bistaratze bateratua"},"菌株树的交互检查与注释":{"en":"Interactive strain-tree inspection and annotation","fr":"Inspection interactive et annotation des arbres","es":"Inspección interactiva y anotación de árboles","eu":"Andui-zuhaitzen ikuskapen eta ohar interaktiboak"},"给定生活史与选择设定的正向演化模拟":{"en":"Forward evolution under specified life history and selection","fr":"Évolution prospective sous cycle de vie et sélection définis","es":"Evolución hacia adelante con ciclo vital y selección definidos","eu":"Aurreranzko eboluzioa bizi-ziklo eta hautespen zehaztuekin"},"中性群体历史、祖先重组与抽样模拟":{"en":"Neutral demography, ancestral recombination and sampling","fr":"Démographie neutre, recombinaison ancestrale et échantillonnage","es":"Demografía neutral, recombinación ancestral y muestreo","eu":"Demografia neutroa, arbasoen birkonbinazioa eta laginketa"},"多亲缘矩阵的遗传方差与敏感性对照":{"en":"Genetic variance and sensitivity across relationship matrices","fr":"Variance génétique et sensibilité aux matrices de parenté","es":"Varianza genética y sensibilidad a matrices de parentesco","eu":"Bariantza genetikoa eta ahaidetasun-matrizeekiko sentikortasuna"},"预先审计酵母倍性、MAF/LD 权重和 GRM 尺度；标准 GREML 不直接传播噪音性状的异方差测量误差，须与误差模型或匹配模拟并列。":{"en":"Audit yeast ploidy, MAF/LD weights and GRM scale first. Standard GREML does not directly propagate heteroskedastic noise-trait measurement error; compare with an error-aware model or matched simulation.","fr":"Auditez ploïdie, poids MAF/LD et échelle GRM. GREML standard ne propage pas directement l’erreur hétéroscédastique du bruit ; comparez à un modèle adapté ou une simulation.","es":"Audite ploidía, pesos MAF/LD y escala GRM. GREML estándar no propaga directamente error heterocedástico del ruido; compare con un modelo de error o simulación.","eu":"Auditatu ploidia, MAF/LD pisuak eta GRM eskala. GREML estandarrak ez du zarata-ezaugarriaren neurketa-errore heterozedastikoa zuzenean hedatzen; alderatu errore-eredu edo simulazio egoki batekin."},"遗传力对亲缘构建的敏感性":{"en":"Heritability sensitivity to relationship construction","fr":"Sensibilité de l’héritabilité à la parenté","es":"Sensibilidad de heredabilidad a la matriz de parentesco","eu":"Heredagarritasunaren sentikortasuna ahaidetasunarekiko"},"按所选模型保存各字段、估计区间与设计匹配的敏感性结果。":{"en":"Save model-specific fields, estimation intervals and design-matched sensitivity results.","fr":"Conservez champs, intervalles et sensibilités adaptés au modèle et au plan.","es":"Guarde campos, intervalos y sensibilidad adaptados al modelo y diseño.","eu":"Gorde ereduari dagozkion eremuak, tarteak eta diseinuari egokitutako sentikortasunak."},"模型定义的单位与区间":{"en":"Model-defined units and intervals","fr":"Unités et intervalles du modèle","es":"Unidades e intervalos del modelo","eu":"Ereduak definitutako unitateak eta tarteak"},"匹配菌株、性状或模拟重复":{"en":"Matched strains, traits or simulation replicates","fr":"Souches, caractères ou simulations appariés","es":"Cepas, rasgos o simulaciones emparejados","eu":"Parekatutako andui, ezaugarri edo simulazio-erreplikak"},"加性、显性与非加性方差":{"en":"Additive, dominance and non-additive variance","fr":"Variances additive, de dominance et non additive","es":"Varianzas aditiva, de dominancia y no aditiva","eu":"Bariantza gehigarria, dominantziakoa eta ez-gehigarria"},"结构变异与剂量的噪音效应":{"en":"Structural-variant and dosage effects on noise","fr":"Effets des variants structuraux et du dosage sur le bruit","es":"Efectos de variantes estructurales y dosis sobre ruido","eu":"Egitura-aldaeren eta dosiaren eraginak zaratan"},"亲本—杂交体调控对比":{"en":"Parent–hybrid regulatory contrasts","fr":"Contrastes régulateurs parents–hybrides","es":"Contrastes reguladores padres–híbridos","eu":"Guraso–hibrido erregulazio-kontrasteak"},"中性校准下的噪音分化":{"en":"Neutral-calibrated noise divergence","fr":"Divergence du bruit calibrée sous neutralité","es":"Divergencia de ruido calibrada bajo neutralidad","eu":"Neutraltasunez kalibratutako zarata-dibergentzia"},"菌株树的支持与不一致性":{"en":"Strain-tree support and discordance","fr":"Support et discordance des arbres","es":"Soporte y discordancia de árboles","eu":"Andui-zuhaitzen sostengua eta desadostasuna"},"噪音性状演变模型比较":{"en":"Noise-trait evolutionary model comparison","fr":"Comparaison des modèles d’évolution du bruit","es":"Comparación de modelos evolutivos de ruido","eu":"Zarata-ezaugarrien eboluzio-ereduen konparazioa"},"祖先噪音状态与区间":{"en":"Ancestral noise states and intervals","fr":"États ancestraux du bruit et intervalles","es":"Estados ancestrales del ruido e intervalos","eu":"Arbasoen zarata-egoerak eta tarteak"},"演化情景与预测校准":{"en":"Evolution scenarios and predictive calibration","fr":"Scénarios évolutifs et calibration prédictive","es":"Escenarios evolutivos y calibración predictiva","eu":"Eboluzio-eszenarioak eta iragarpen-kalibrazioa"},"均值与噪音性状的遗传相关":{"en":"Genetic correlation of mean and noise traits","fr":"Corrélation génétique entre moyenne et bruit","es":"Correlación genética entre media y ruido","eu":"Batezbestekoaren eta zarataren korrelazio genetikoa"},"G 为明确尺度与亲缘模型下的遗传协方差矩阵；方差接近零时，相关估计可能不稳定。":{"en":"G is the genetic covariance matrix for the declared scale and relationship model; correlations can be unstable when variances approach zero.","fr":"G est la covariance génétique sur l’échelle et sous le modèle déclarés ; près de zéro, les corrélations peuvent être instables.","es":"G es la covarianza genética de la escala y modelo declarados; las correlaciones pueden ser inestables cerca de varianzas cero.","eu":"G eskala eta ahaidetasun-eredu zehaztuko kobariantza genetikoa da; bariantzak zerotik hurbil direnean korrelazioak ezegonkorrak izan daitezke."},"比较共享遗传变化，并传播两个性状的估计误差。":{"en":"Compare shared genetic variation while propagating both traits’ estimation error.","fr":"Comparez la variation génétique partagée en propageant l’erreur des deux caractères.","es":"Compare variación genética compartida propagando error de ambos rasgos.","eu":"Alderatu partekatutako aldakortasun genetikoa bi ezaugarrien errorea hedatuz."}});
